-- Catch-up script: run after 00_setup_source.sql, before "Lab 3 - Build the Gold Star".
-- Generated by duckdb/validate.py from Track 3 - Study Case.md; do not edit by hand.

CREATE SCHEMA IF NOT EXISTS bronze;

CREATE SCHEMA IF NOT EXISTS silver;

CREATE SCHEMA IF NOT EXISTS gold;

CREATE SCHEMA IF NOT EXISTS sandbox;

CREATE OR REPLACE TABLE bronze.sales_order_line  AS SELECT *, current_timestamp AS _loaded_at, 'source.sales_order_line'  AS _source FROM source.sales_order_line;

CREATE OR REPLACE TABLE bronze.sales_order       AS SELECT *, current_timestamp AS _loaded_at, 'source.sales_order'       AS _source FROM source.sales_order;

CREATE OR REPLACE TABLE bronze.outlet            AS SELECT *, current_timestamp AS _loaded_at, 'source.outlet'            AS _source FROM source.outlet;

CREATE OR REPLACE TABLE bronze.sku               AS SELECT *, current_timestamp AS _loaded_at, 'source.sku'               AS _source FROM source.sku;

CREATE OR REPLACE TABLE bronze.distributor       AS SELECT *, current_timestamp AS _loaded_at, 'source.distributor'       AS _source FROM source.distributor;

CREATE OR REPLACE TABLE bronze.distributor_stock AS SELECT *, current_timestamp AS _loaded_at, 'source.distributor_stock' AS _source FROM source.distributor_stock;

CREATE OR REPLACE TABLE bronze.area              AS SELECT *, current_timestamp AS _loaded_at, 'source.area'              AS _source FROM source.area;

CREATE OR REPLACE TABLE bronze.region            AS SELECT *, current_timestamp AS _loaded_at, 'source.region'            AS _source FROM source.region;

CREATE OR REPLACE TABLE silver.outlet AS
SELECT o.ot_outlet_id AS outlet_id, o.ot_name AS outlet_name, o.ot_channel AS channel,
       a.ar_name AS area, r.rg_name AS region
FROM bronze.outlet o
JOIN bronze.area a   ON o.ot_area_id = a.ar_area_id
JOIN bronze.region r ON a.ar_region_id = r.rg_region_id;

CREATE OR REPLACE TABLE silver.distributor AS
SELECT d.dt_distributor_id AS distributor_id, d.dt_name AS distributor_name,
       a.ar_name AS area, r.rg_name AS region
FROM bronze.distributor d
JOIN bronze.area a   ON d.dt_area_id = a.ar_area_id
JOIN bronze.region r ON a.ar_region_id = r.rg_region_id;

CREATE OR REPLACE TABLE silver.sku AS
SELECT sk_sku_id AS sku_id, sk_name AS sku_name, sk_brand AS brand, sk_segment AS segment
FROM bronze.sku;

CREATE OR REPLACE TABLE silver.distributor_stock AS
SELECT st_sku_id AS sku_id, st_distributor_id AS distributor_id,
       st_stock_slof AS stock_slof, st_unit_cost_slof AS unit_cost_slof
FROM bronze.distributor_stock;

CREATE OR REPLACE TABLE silver.sales_line AS
SELECT
    l.sl_order_id       AS order_id,
    l.sl_line_no        AS line_no,
    o.so_order_date     AS order_date,
    o.so_order_source   AS order_source,
    o.so_outlet_id      AS outlet_id,
    l.sl_sku_id         AS sku_id,
    l.sl_distributor_id AS distributor_id,
    l.sl_qty_slof       AS qty_slof,
    l.sl_gross_amount   AS gross_amount,
    l.sl_discount       AS discount,
    -- company definition of net sales: after discount, before excise and VAT
    l.sl_gross_amount * (1 - l.sl_discount) AS net_amount,
    l.sl_excise_amount  AS excise_amount,
    l.sl_ship_date      AS ship_date,
    l.sl_promised_date  AS promised_date,
    l.sl_delivery_date  AS delivery_date
FROM bronze.sales_order_line l
JOIN bronze.sales_order o ON l.sl_order_id = o.so_order_id
-- keep the latest load of each order line
QUALIFY ROW_NUMBER() OVER (PARTITION BY l.sl_order_id, l.sl_line_no ORDER BY l._loaded_at DESC) = 1
ORDER BY order_date;

SELECT 'catch-up done' AS status;